use peppy_desktop_api::{
    DraftConflictView, DraftNoticeView, DraftSyncStateView, DraftSyncView, DraftView,
};
use std::{env, fs, path::Path};
use ts_rs::TS;

fn contracts() -> String {
    let declarations = [
        DraftSyncStateView::decl(),
        DraftNoticeView::decl(),
        DraftConflictView::decl(),
        DraftSyncView::decl(),
        DraftView::decl(),
    ]
    .join("\n")
    .replace("type ", "export type ");
    format!(
        "// Generated by ts-rs; do not edit.\n\nimport type {{ AttachmentView }} from \"./message\";\n\n{declarations}\n"
    )
}

fn main() {
    let check = env::args().skip(1).any(|arg| arg == "--check");
    let path = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../packages/generated/src/draft.ts");
    if check {
        assert_eq!(
            fs::read_to_string(&path).unwrap_or_default(),
            contracts(),
            "generated contracts are stale; rerun generate-draft-contracts"
        );
    } else {
        fs::write(path, contracts()).expect("write generated draft contracts");
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn draft_typescript_is_current() {
        let path =
            Path::new(env!("CARGO_MANIFEST_DIR")).join("../../packages/generated/src/draft.ts");
        assert_eq!(fs::read_to_string(path).unwrap(), contracts());
    }
}
